1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	<meta charset="utf-8">
5	<meta name="viewport" content="width=device-width, initial-scale=1">
6	<title>Bookmarks — prototype</title>
7	<style>
8	  :root {
9	    --bg: #f6f7f9;
10	    --card: #ffffff;
11	    --ink: #1c2330;
12	    --muted: #6b7480;
13	    --line: #e6e9ee;
14	    --accent: #2f6df6;
15	  }
16	  * { box-sizing: border-box; }
17	  body {
18	    margin: 0;
19	    background: var(--bg);
20	    color: var(--ink);
21	    font: 15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
22	  }
23	  .wrap { max-width: 720px; margin: 0 auto; padding: 40px 20px 80px; }
24	  h1 { font-size: 22px; margin: 0 0 4px; }
25	  .sub { color: var(--muted); margin: 0 0 28px; }
26	
27	  .saver {
28	    display: flex; gap: 10px; margin-bottom: 8px;
29	  }
30	  .saver input {
31	    flex: 1; padding: 13px 15px; font-size: 15px;
32	    border: 1px solid var(--line); border-radius: 10px; background: var(--card);
33	    outline: none;
34	  }
35	  .saver input:focus { border-color: var(--accent); }
36	  .saver button {
37	    padding: 0 20px; font-size: 15px; font-weight: 600; color: #fff;
38	    background: var(--accent); border: none; border-radius: 10px; cursor: pointer;
39	  }
40	  .saver button:disabled { opacity: .5; cursor: default; }
41	  .hint { color: var(--muted); font-size: 13px; margin: 0 0 26px; }
42	
43	  .count { color: var(--muted); font-size: 13px; margin: 0 0 12px; }
44	
45	  ul { list-style: none; margin: 0; padding: 0; }
46	  li.item {
47	    background: var(--card); border: 1px solid var(--line); border-radius: 12px;
48	    padding: 14px 16px; margin-bottom: 10px; display: flex; gap: 14px; align-items: flex-start;
49	  }
50	  .favicon {
51	    width: 32px; height: 32px; border-radius: 8px; flex: none;
52	    background: #eef1f6; display: grid; place-items: center; font-size: 16px;
53	    overflow: hidden;
54	  }
55	  .favicon img { width: 100%; height: 100%; object-fit: cover; }
56	  .body { min-width: 0; flex: 1; }
57	  .title { font-weight: 600; font-size: 15.5px; margin: 0 0 2px; }
58	  .title a { color: var(--ink); text-decoration: none; }
59	  .title a:hover { text-decoration: underline; }
60	  .desc { color: var(--muted); font-size: 13.5px; margin: 0 0 5px;
61	          display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden; }
62	  .meta { color: var(--muted); font-size: 12.5px; }
63	
64	  li.resolving { color: var(--muted); }
65	  .spinner {
66	    width: 16px; height: 16px; border: 2px solid var(--line);
67	    border-top-color: var(--accent); border-radius: 50%;
68	    animation: spin .7s linear infinite;
69	  }
70	  @keyframes spin { to { transform: rotate(360deg); } }
71	
72	  .empty { text-align: center; color: var(--muted); padding: 40px 0; }
73	</style>
74	</head>
75	<body>
76	  <div class="wrap">
77	    <h1>My Bookmarks</h1>
78	    <p class="sub">Paste a link. It sorts itself out.</p>
79	
80	    <div class="saver">
81	      <input id="url" type="text" placeholder="Paste a link and press Save…" autocomplete="off">
82	      <button id="save">Save</button>
83	    </div>
84	    <p class="hint">Try pasting something like <code>https://www.nytimes.com/…/best-pasta-recipes.html</code> — or any real link you have.</p>
85	
86	    <p class="count" id="count"></p>
87	    <ul id="list"></ul>
88	    <div class="empty" id="empty">Nothing saved yet. Paste your first link above.</div>
89	  </div>
90	
91	<script>
92	// --- Prototype-only simulation of "figuring out the page" -------------------
93	// A real version fetches the page and reads its title/description. Here we
94	// simulate that resolution so the *behaviour* can be judged.
95	const KNOWN = {
96	  "nytimes.com":      { site: "The New York Times", emoji: "🗞️" },
97	  "cooking.nytimes.com": { site: "NYT Cooking", emoji: "🍝" },
98	  "github.com":       { site: "GitHub", emoji: "🐙" },
99	  "youtube.com":      { site: "YouTube", emoji: "▶️" },
100	  "wikipedia.org":    { site: "Wikipedia", emoji: "📚" },
101	  "medium.com":       { site: "Medium", emoji: "✍️" },
102	  "arxiv.org":        { site: "arXiv", emoji: "📄" },
103	  "bbc.com":          { site: "BBC", emoji: "📰" },
104	  "stackoverflow.com":{ site: "Stack Overflow", emoji: "💬" },
105	};
106	
107	function titleCase(s) {
108	  return s.replace(/[-_]+/g, " ").replace(/\.[a-z]{2,4}$/i, "").trim()
109	          .replace(/\s+/g, " ")
110	          .replace(/\b\w/g, c => c.toUpperCase());
111	}
112	
113	function resolve(rawUrl) {
114	  let url;
115	  try { url = new URL(rawUrl.includes("://") ? rawUrl : "https://" + rawUrl); }
116	  catch { return null; }
117	  const host = url.hostname.replace(/^www\./, "");
118	  const key = Object.keys(KNOWN).find(k => host === k || host.endsWith("." + k)) || host;
119	  const known = KNOWN[key] || { site: titleCase(host.split(".")[0]), emoji: "🔖" };
120	
121	  // Derive a readable title from the last meaningful path segment.
122	  const seg = url.pathname.split("/").filter(Boolean).pop() || "";
123	  let title = seg ? titleCase(decodeURIComponent(seg)) : known.site + " — home";
124	  if (title.length > 70) title = title.slice(0, 67) + "…";
125	
126	  const desc = "A page on " + known.site + ". (In the real app this line shows the page's own summary.)";
127	  return { url: url.href, host, site: known.site, emoji: known.emoji, title, desc };
128	}
129	
130	// --- List rendering ---------------------------------------------------------
131	const list = document.getElementById("list");
132	const empty = document.getElementById("empty");
133	const countEl = document.getElementById("count");
134	const items = [];
135	
136	function render() {
137	  list.innerHTML = "";
138	  empty.style.display = items.length ? "none" : "block";
139	  countEl.textContent = items.length ? items.length + (items.length === 1 ? " link saved" : " links saved") : "";
140	  for (const it of items) {
141	    const li = document.createElement("li");
142	    li.className = "item";
143	    li.innerHTML = `
144	      <div class="favicon">${it.emoji}</div>
145	      <div class="body">
146	        <p class="title"><a href="${it.url}" target="_blank" rel="noopener">${it.title}</a></p>
147	        <p class="desc">${it.desc}</p>
148	        <p class="meta">${it.site} · ${it.host}</p>
149	      </div>`;
150	    list.appendChild(li);
151	  }
152	}
153	
154	function showResolving() {
155	  empty.style.display = "none";
156	  const li = document.createElement("li");
157	  li.className = "item resolving";
158	  li.innerHTML = `<div class="favicon"><div class="spinner"></div></div>
159	    <div class="body"><p class="title">Figuring out this page…</p>
160	    <p class="meta">Reading the title and summary for you</p></div>`;
161	  list.insertBefore(li, list.firstChild);
162	  return li;
163	}
164	
165	const input = document.getElementById("url");
166	const btn = document.getElementById("save");
167	
168	function save() {
169	  const raw = input.value.trim();
170	  if (!raw) return;
171	  const resolved = resolve(raw);
172	  if (!resolved) { alert("That doesn't look like a link yet."); return; }
173	  input.value = "";
174	  const placeholder = showResolving();
175	  // Simulate the short moment of fetching the page.
176	  setTimeout(() => {
177	    placeholder.remove();
178	    items.unshift(resolved);
179	    render();
180	  }, 850);
181	}
182	
183	btn.addEventListener("click", save);
184	input.addEventListener("keydown", e => { if (e.key === "Enter") save(); });
185	render();
186	</script>
187	</body>
188	</html>
