6	<title>Bookmarks — prototype (v2)</title>
7	<style>
8	  :root {
9	    --bg: #f6f7f9; --card: #ffffff; --ink: #1c2330; --muted: #6b7480;
10	    --line: #e6e9ee; --accent: #2f6df6; --flash: #fff6d6;
11	  }
12	  * { box-sizing: border-box; }
13	  body { margin: 0; background: var(--bg); color: var(--ink);
14	    font: 15px/1.5 -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif; }
15	  .wrap { max-width: 720px; margin: 0 auto; padding: 40px 20px 80px; }
16	  h1 { font-size: 22px; margin: 0 0 4px; }
17	  .sub { color: var(--muted); margin: 0 0 28px; }
18	
19	  .saver { display: flex; gap: 10px; margin-bottom: 8px; }
20	  .saver input { flex: 1; padding: 13px 15px; font-size: 15px;
21	    border: 1px solid var(--line); border-radius: 10px; background: var(--card); outline: none; }
22	  .saver input:focus { border-color: var(--accent); }
23	  .saver button { padding: 0 20px; font-size: 15px; font-weight: 600; color: #fff;
24	    background: var(--accent); border: none; border-radius: 10px; cursor: pointer; }
25	  .hint { color: var(--muted); font-size: 13px; margin: 0 0 20px; }
26	
27	  .notice { background: #eef3ff; border: 1px solid #d4e0ff; color: #234; border-radius: 10px;
28	    padding: 10px 14px; font-size: 13.5px; margin: 0 0 18px; display: none; }
29	  .count { color: var(--muted); font-size: 13px; margin: 0 0 12px; }
30	
31	  ul { list-style: none; margin: 0; padding: 0; }
32	  li.item { background: var(--card); border: 1px solid var(--line); border-radius: 12px;
33	    padding: 14px 16px; margin-bottom: 10px; display: flex; gap: 14px; align-items: flex-start;
34	    transition: background .25s, border-color .25s; }
35	  li.item.flash { background: var(--flash); border-color: #f0e3a8; }
36	  .favicon { width: 32px; height: 32px; border-radius: 8px; flex: none;
37	    background: #eef1f6; display: grid; place-items: center; font-size: 16px; }
38	  .body { min-width: 0; flex: 1; }
39	  .title { font-weight: 600; font-size: 15.5px; margin: 0 0 2px; }
40	  .title a { color: var(--ink); text-decoration: none; }
41	  .title a:hover { text-decoration: underline; }
42	  .desc { color: var(--muted); font-size: 13.5px; margin: 0 0 5px; }
43	  .meta { color: var(--muted); font-size: 12.5px; }
44	
45	  /* editable affordance */
46	  .editable { cursor: text; border-radius: 5px; padding: 1px 4px; margin-left: -4px;
47	    border: 1px solid transparent; }
48	  .editable:hover { background: #f2f4f8; }
49	  .pencil { opacity: 0; font-size: 12px; color: var(--muted); margin-left: 6px; }
50	  .body:hover .pencil { opacity: .6; }
51	  .edit-field { width: 100%; font: inherit; color: var(--ink);
52	    border: 1px solid var(--accent); border-radius: 6px; padding: 4px 6px; outline: none; }
53	  textarea.edit-field { resize: vertical; min-height: 40px; }
54	
55	  .resolving { color: var(--muted); }
56	  .spinner { width: 16px; height: 16px; border: 2px solid var(--line);
57	    border-top-color: var(--accent); border-radius: 50%; animation: spin .7s linear infinite; }
58	  @keyframes spin { to { transform: rotate(360deg); } }
59	  .empty { text-align: center; color: var(--muted); padding: 40px 0; }
60	</style>
61	</head>
62	<body>
63	  <div class="wrap">
64	    <h1>My Bookmarks</h1>
65	    <p class="sub">Paste a link. It sorts itself out.</p>
66	
67	    <div class="saver">
68	      <input id="url" type="text" placeholder="Paste a link and press Save…" autocomplete="off">
69	      <button id="save">Save</button>
70	    </div>
71	    <p class="hint">Tip: try saving the <b>same link twice</b>, and try <b>clicking a title or its summary</b> to rename it.</p>
72	
73	    <div class="notice" id="notice"></div>
74	    <p class="count" id="count"></p>
75	    <ul id="list"></ul>
76	    <div class="empty" id="empty">Nothing saved yet. Paste your first link above.</div>
77	  </div>
78	
79	<script>
80	const KNOWN = {
81	  "nytimes.com": { site: "The New York Times", emoji: "🗞️" },
82	  "cooking.nytimes.com": { site: "NYT Cooking", emoji: "🍝" },
83	  "github.com": { site: "GitHub", emoji: "🐙" },
84	  "youtube.com": { site: "YouTube", emoji: "▶️" },
85	  "wikipedia.org": { site: "Wikipedia", emoji: "📚" },
86	  "medium.com": { site: "Medium", emoji: "✍️" },
87	  "bbc.com": { site: "BBC", emoji: "📰" },
88	  "stackoverflow.com": { site: "Stack Overflow", emoji: "💬" },
89	};
90	function titleCase(s){return s.replace(/[-_]+/g," ").replace(/\.[a-z]{2,4}$/i,"").trim()
91	  .replace(/\s+/g," ").replace(/\b\w/g,c=>c.toUpperCase());}
92	
93	// Normalise so trivially-different forms of the same link count as the same.
94	function normalize(rawUrl){
95	  let url; try { url = new URL(rawUrl.includes("://")?rawUrl:"https://"+rawUrl); } catch { return null; }
96	  const host = url.hostname.replace(/^www\./,"").toLowerCase();
97	  let path = url.pathname.replace(/\/+$/,"");
98	  return host + path + (url.search||"");
99	}
100	function resolve(rawUrl){
101	  let url; try { url = new URL(rawUrl.includes("://")?rawUrl:"https://"+rawUrl); } catch { return null; }
102	  const host = url.hostname.replace(/^www\./,"");
103	  const key = Object.keys(KNOWN).find(k=>host===k||host.endsWith("."+k))||host;
104	  const known = KNOWN[key]||{site:titleCase(host.split(".")[0]),emoji:"🔖"};
105	  const seg = url.pathname.split("/").filter(Boolean).pop()||"";
106	  let title = seg?titleCase(decodeURIComponent(seg)):known.site+" — home";
107	  if(title.length>70) title=title.slice(0,67)+"…";
108	  return { id: normalize(rawUrl), url:url.href, host, site:known.site, emoji:known.emoji,
109	    title, desc:"A page on "+known.site+". (In the real app this line shows the page's own summary.)" };
110	}
111	
112	const list=document.getElementById("list"), empty=document.getElementById("empty"),
113	  countEl=document.getElementById("count"), notice=document.getElementById("notice");
114	const items=[];
115	
116	function showNotice(msg){ notice.textContent=msg; notice.style.display="block";
117	  clearTimeout(showNotice._t); showNotice._t=setTimeout(()=>notice.style.display="none",4000); }
118	
119	function render(){
120	  list.innerHTML=""; empty.style.display=items.length?"none":"block";
121	  countEl.textContent=items.length?items.length+(items.length===1?" link saved":" links saved"):"";
122	  items.forEach((it)=>{
123	    const li=document.createElement("li"); li.className="item"; li.dataset.id=it.id;
124	    li.innerHTML=`
125	      <div class="favicon">${it.emoji}</div>
126	      <div class="body">
127	        <p class="title"><a href="${it.url}" target="_blank" rel="noopener">${escapeHtml(it.title)}</a><span class="pencil">✎</span></p>
128	        <p class="desc"><span class="editable descedit">${escapeHtml(it.desc)}</span></p>
129	        <p class="meta">${it.site} · ${it.host}</p>
130	      </div>`;
131	    // click the title text (not the link) to rename
132	    const titleP=li.querySelector(".title");
133	    titleP.addEventListener("click",e=>{ if(e.target.tagName==="A") return; startEdit(it,"title",titleP,false); });
134	    li.querySelector(".pencil").addEventListener("click",()=>startEdit(it,"title",titleP,false));
135	    li.querySelector(".descedit").addEventListener("click",()=>startEdit(it,"desc",li.querySelector(".desc"),true));
136	    list.appendChild(li);
137	  });
138	}
139	function escapeHtml(s){return s.replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}
140	
141	function startEdit(it,field,container,multiline){
142	  const current=it[field];
143	  const el=document.createElement(multiline?"textarea":"input");
144	  el.className="edit-field"; el.value=current;
145	  container.replaceWith(wrap(el,container,field==="title"?"title":"desc"));
146	  el.focus(); el.select();
147	  const commit=()=>{ const v=el.value.trim(); if(v) it[field]=v; render(); };
148	  el.addEventListener("keydown",e=>{
149	    if(e.key==="Enter"&&!multiline){e.preventDefault();commit();}
150	    if(e.key==="Escape"){render();}
151	  });
152	  el.addEventListener("blur",commit);
153	}
154	function wrap(el,oldContainer,cls){ const p=document.createElement("p"); p.className=cls; p.appendChild(el); return p; }
155	
156	function flash(id){
157	  const li=list.querySelector(`li[data-id="${cssEscape(id)}"]`);
158	  if(!li) return;
159	  li.classList.add("flash"); li.scrollIntoView({behavior:"smooth",block:"center"});
160	  setTimeout(()=>li.classList.remove("flash"),1600);
161	}
162	function cssEscape(s){return s.replace(/["\\]/g,"\\$&");}
163	
164	function showResolving(){
165	  empty.style.display="none";
166	  const li=document.createElement("li"); li.className="item resolving";
167	  li.innerHTML=`<div class="favicon"><div class="spinner"></div></div>
168	    <div class="body"><p class="title">Figuring out this page…</p>
169	    <p class="meta">Reading the title and summary for you</p></div>`;
170	  list.insertBefore(li,list.firstChild); return li;
171	}
172	
173	const input=document.getElementById("url"), btn=document.getElementById("save");
174	function save(){
175	  const raw=input.value.trim(); if(!raw) return;
176	  const resolved=resolve(raw);
177	  if(!resolved){ alert("That doesn't look like a link yet."); return; }
178	  input.value="";
179	  // Already saved? Don't duplicate — take them to the one they have.
180	  const existing=items.find(x=>x.id===resolved.id);
181	  if(existing){ showNotice("You already saved this one — here it is. You can rename it below."); flash(existing.id); return; }
182	  const placeholder=showResolving();
183	  setTimeout(()=>{ placeholder.remove(); items.unshift(resolved); render(); },850);
184	}
185	btn.addEventListener("click",save);
186	input.addEventListener("keydown",e=>{if(e.key==="Enter")save();});
187	render();
188	</script>
189	</body>
190	</html>
