105	<script>
106	const KNOWN={ "nytimes.com":{site:"The New York Times",emoji:"🗞️"},
107	  "cooking.nytimes.com":{site:"NYT Cooking",emoji:"🍝"}, "github.com":{site:"GitHub",emoji:"🐙"},
108	  "youtube.com":{site:"YouTube",emoji:"▶️"}, "wikipedia.org":{site:"Wikipedia",emoji:"📚"},
109	  "bbc.com":{site:"BBC",emoji:"📰"}, "stackoverflow.com":{site:"Stack Overflow",emoji:"💬"} };
110	// Tracking params that are safe to ignore when deciding "same link".
111	const JUNK=new Set(["utm_source","utm_medium","utm_campaign","utm_term","utm_content",
112	  "fbclid","gclid","mc_cid","mc_eid","igshid","ref","ref_src","spm","_hsenc","_hsmi"]);
113	
114	function titleCase(s){return s.replace(/[-_]+/g," ").replace(/\.[a-z]{2,4}$/i,"").trim()
115	  .replace(/\s+/g," ").replace(/\b\w/g,c=>c.toUpperCase());}
116	function parse(raw){ try { return new URL(raw.includes("://")?raw:"https://"+raw); } catch { return null; } }
117	
118	// Normalise: drop www, trailing slash, and known tracking params — but KEEP
119	// meaningful params (like ?v=… that pick which page you mean).
120	function normalize(raw){
121	  const u=parse(raw); if(!u) return null;
122	  const host=u.hostname.replace(/^www\./,"").toLowerCase();
123	  const path=u.pathname.replace(/\/+$/,"");
124	  const kept=[...u.searchParams.entries()].filter(([k])=>!JUNK.has(k.toLowerCase()))
125	    .sort((a,b)=>a[0]<b[0]?-1:1).map(([k,v])=>k+"="+v).join("&");
126	  return host+path+(kept?"?"+kept:"");
127	}
128	function resolve(raw){
129	  const u=parse(raw); if(!u) return null;
130	  const host=u.hostname.replace(/^www\./,"");
131	  const key=Object.keys(KNOWN).find(k=>host===k||host.endsWith("."+k))||host;
132	  const known=KNOWN[key]||{site:titleCase(host.split(".")[0]),emoji:"🔖"};
133	  const seg=u.pathname.split("/").filter(Boolean).pop()||"";
134	  let title=seg?titleCase(decodeURIComponent(seg)):known.site+" — home";
135	  if(title.length>70) title=title.slice(0,67)+"…";
136	  return { id:normalize(raw), url:u.href, host, site:known.site, emoji:known.emoji, title,
137	    desc:"A page on "+known.site+". (Real app shows the page's own summary here.)" };
138	}
139	
140	let mode="button";
141	const MODEHINTS={
142	  button:"A · A small “Rename” control sits on every row, always visible. Click the link to open; click Rename to edit.",
143	  menu:"B · Each row has a “⋯” button that opens a little menu — Rename lives there, with room for more tidy-up actions later.",
144	  editmode:"C · An “Edit” button flips the whole row into a form with labelled fields — made to hold more than just the title later."
145	};
146	const list=document.getElementById("list"), empty=document.getElementById("empty"),
147	  countEl=document.getElementById("count"), notice=document.getElementById("notice"),
148	  modehint=document.getElementById("modehint");
149	
150	const items=[
151	  { id:normalize("nytimes.com/2024/recipes/pasta-al-limone-recipe-8813.html"),
152	    url:"https://www.nytimes.com/2024/recipes/pasta-al-limone-recipe-8813.html",
153	    host:"nytimes.com", site:"NYT Cooking", emoji:"🍝",
154	    title:"Pasta Al Limone Recipe 8813", // deliberately garbled
155	    desc:"A page on NYT Cooking. (Real app shows the page's own summary here.)" },
156	  { id:normalize("bbc.com/news/technology-latest"),
157	    url:"https://www.bbc.com/news/technology-latest", host:"bbc.com", site:"BBC", emoji:"📰",
158	    title:"Technology Latest", desc:"A page on BBC. (Real app shows the page's own summary here.)" },
159	];
160	
161	function showNotice(m){ notice.textContent=m; notice.style.display="block";
162	  clearTimeout(showNotice._t); showNotice._t=setTimeout(()=>notice.style.display="none",4000); }
163	function esc(s){return s.replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}
164	function cssEsc(s){return s.replace(/["\\]/g,"\\$&");}
165	
166	let editing=null; // id currently in edit-mode form (mode C)
167	
168	function render(){
169	  closeMenus();
170	  list.innerHTML=""; empty.style.display=items.length?"none":"block";
171	  countEl.textContent=items.length?items.length+(items.length===1?" link saved":" links saved"):"";
172	  modehint.textContent=MODEHINTS[mode];
173	  items.forEach(it=>{
174	    const li=document.createElement("li"); li.className="item"; li.dataset.id=it.id;
175	
176	    if(mode==="editmode" && editing===it.id){
177	      li.innerHTML=`<div class="favicon">${it.emoji}</div>
178	        <div class="editform">
179	          <label>Title</label><input class="edit-field t" value="${esc(it.title)}">
180	          <label>Summary</label><textarea class="edit-field d">${esc(it.desc)}</textarea>
181	          <button class="done">Done</button>
182	        </div>`;
183	      const t=li.querySelector(".t"), d=li.querySelector(".d");
184	      li.querySelector(".done").addEventListener("click",()=>{
185	        if(t.value.trim()) it.title=t.value.trim();
186	        if(d.value.trim()) it.desc=d.value.trim(); editing=null; render();
187	      });
188	      t.focus(); t.select();
189	      list.appendChild(li); return;
190	    }
191	
192	    // shared body
193	    li.innerHTML=`<div class="favicon">${it.emoji}</div>
194	      <div class="body">
195	        <p class="title"><a href="${it.url}" target="_blank" rel="noopener">${esc(it.title)}</a></p>
196	        <p class="desc"><span class="descedit">${esc(it.desc)}</span></p>
197	        <p class="meta">${it.site} · ${it.host}</p>
198	      </div>
199	      <div class="actions"></div>`;
200	    // summary inline edit (identical across modes)
201	    li.querySelector(".descedit").addEventListener("click",()=>inlineEdit(it,"desc",li.querySelector(".desc"),true));
202	
203	    const actions=li.querySelector(".actions");
204	    if(mode==="button"){
205	      const b=document.createElement("button"); b.className="btn"; b.textContent="✎ Rename";
206	      b.addEventListener("click",()=>inlineEdit(it,"title",li.querySelector(".title"),false));
207	      actions.appendChild(b);
208	    } else if(mode==="menu"){
209	      const b=document.createElement("button"); b.className="btn"; b.textContent="⋯";
210	      b.addEventListener("click",e=>{ e.stopPropagation(); openMenu(li,it); });
211	      actions.appendChild(b);
212	    } else if(mode==="editmode"){
213	      const b=document.createElement("button"); b.className="btn"; b.textContent="Edit";
214	      b.addEventListener("click",()=>{ editing=it.id; render(); });
215	      actions.appendChild(b);
216	    }
217	    list.appendChild(li);
218	  });
219	}
220	
221	function inlineEdit(it,field,container,multiline){
222	  const el=document.createElement(multiline?"textarea":"input");
223	  el.className="edit-field"; el.value=it[field];
224	  const p=document.createElement("p"); p.className=container.className; p.appendChild(el);
225	  container.replaceWith(p); el.focus(); el.select();
226	  const commit=()=>{ if(el.value.trim()) it[field]=el.value.trim(); render(); };
227	  el.addEventListener("keydown",e=>{ if(e.key==="Enter"&&!multiline){e.preventDefault();commit();}
228	    if(e.key==="Escape") render(); });
229	  el.addEventListener("blur",commit);
230	}
231	
232	function openMenu(li,it){
233	  closeMenus();
234	  const m=document.createElement("div"); m.className="menu";
235	  m.innerHTML=`<button data-a="rename">✎ Rename title</button>
236	    <button data-a="desc">✍️ Edit summary</button>
237	    <button class="future" disabled>＋ More tidy-up (later)</button>`;
238	  m.querySelector('[data-a="rename"]').addEventListener("click",()=>{ closeMenus(); inlineEdit(it,"title",li.querySelector(".title"),false); });
239	  m.querySelector('[data-a="desc"]').addEventListener("click",()=>{ closeMenus(); inlineEdit(it,"desc",li.querySelector(".desc"),true); });
240	  li.appendChild(m); m.style.display="block";
241	}
242	function closeMenus(){ document.querySelectorAll(".menu").forEach(m=>m.remove()); }
243	document.addEventListener("click",e=>{ if(!e.target.closest(".menu")&&!e.target.closest(".actions")) closeMenus(); });
244	
245	function flash(id){ const li=list.querySelector(`li[data-id="${cssEsc(id)}"]`); if(!li) return;
246	  li.classList.add("flash"); li.scrollIntoView({behavior:"smooth",block:"center"});
247	  setTimeout(()=>li.classList.remove("flash"),1600); }
248	
249	const input=document.getElementById("url"), btn=document.getElementById("save");
250	function save(){
251	  const raw=input.value.trim(); if(!raw) return;
252	  const r=resolve(raw); if(!r){ alert("That doesn't look like a link yet."); return; }
253	  input.value="";
254	  const existing=items.find(x=>x.id===r.id);
255	  if(existing){ showNotice("You already saved this one — here it is. (Even with the tracking junk, it's the same page.)"); flash(existing.id); return; }
256	  const li=document.createElement("li"); li.className="item"; empty.style.display="none";
257	  li.innerHTML=`<div class="favicon"><div class="spinner"></div></div>
258	    <div class="body"><p class="title">Figuring out this page…</p><p class="meta">Reading the title and summary</p></div>`;
259	  list.insertBefore(li,list.firstChild);
260	  setTimeout(()=>{ items.unshift(r); render(); },850);
261	}
262	btn.addEventListener("click",save);
263	input.addEventListener("keydown",e=>{ if(e.key==="Enter") save(); });
264	
265	document.querySelectorAll(".switch button").forEach(b=>{
266	  b.addEventListener("click",()=>{ mode=b.dataset.mode; editing=null;
267	    document.querySelectorAll(".switch button").forEach(x=>x.classList.toggle("on",x===b)); render(); });
268	});
269	render();
270	</script>
