function tokenize(q){ const t=[]; const re=/"([^"]+)"|(\S+)/g; let m;
  while((m=re.exec(q))!==null){ const s=(m[1]!==undefined?m[1]:m[2]).trim().toLowerCase(); if(s) t.push(s); }
  return t; }
// Every word must appear somewhere (any order); a quoted token must appear intact.
function matches(it,tokens){ const hay=(it.title+" "+it.desc+" "+it.site).toLowerCase();
  return tokens.every(t=>hay.includes(t)); }
function reEsc(s){ return s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&"); }
function hi(text,tokens){ if(!tokens.length) return esc(text);
  const re=new RegExp("("+tokens.map(reEsc).join("|")+")","gi"); const out=[]; let last=0, m;
