  const known=KNOWN[key]||{site:titleCase(host.split(".")[0]),emoji:"🔖"};
  const seg=u.pathname.split("/").filter(Boolean).pop()||"";
  let title=seg?titleCase(decodeURIComponent(seg)):known.site+" — home";
  return { url:u.href, host, site:known.site, emoji:known.emoji, title,
    desc:"A page on "+known.site+".", failed:false }; }

// Couldn't read the page: SAVE IT ANYWAY so nothing is lost. Fall back to the address
// as the title, flag that it needs a name, and invite a quick fix.
function resolveFailed(raw){ const u=parse(raw); const host=u.hostname.replace(/^www\./,"");
  return { url:u.href, host, site:host, emoji:"🔖", title:null, /* no readable title */
    desc:"", failed:true }; }

const list=document.getElementById("list"), empty=document.getElementById("empty"),
  countEl=document.getElementById("count"), errEl=document.getElementById("err"),
  urlEl=document.getElementById("url"), simfail=document.getElementById("simfail");
const items=[]; let editing=null;

function esc(s){return s.replace(/[&<>"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;"}[c]));}
function render(){
  list.innerHTML=""; empty.style.display=items.length?"none":"block";
  countEl.textContent=items.length?items.length+(items.length===1?" link saved":" links saved"):"";
  items.forEach((it,idx)=>{
    const li=document.createElement("li"); li.className="item"+(it.failed&&!it.title?" unread-fail":"");
    if(editing===idx){
      li.innerHTML=`<div class="favicon">${it.emoji}</div>
        <div class="body">
          <label style="font-size:12px;color:var(--muted)">Title</label>
          <input class="edit-field t" value="${esc(it.title||"")}" placeholder="Give it a name you'll recognise">
          <div style="margin-top:10px;display:flex;gap:8px">
            <button class="btn done" style="background:var(--accent);color:#fff;border:none">Done</button>
            <button class="btn cancel">Cancel</button>
          </div>
        </div>`;
      li.querySelector(".t").focus();
      li.querySelector(".done").addEventListener("click",()=>{ const v=li.querySelector(".t").value.trim();
        if(v){ it.title=v; } editing=null; render(); });
      li.querySelector(".cancel").addEventListener("click",()=>{ editing=null; render(); });
      list.appendChild(li); return;
    }
    const titleHtml = it.title
      ? `<a href="${it.url}" target="_blank" rel="noopener">${esc(it.title)}</a>`
      : `<span class="raw">${esc(it.url)}</span>`;
    const note = (it.failed && !it.title)
      ? `<div><span class="warnnote">⚠️ Couldn’t read this page automatically — it’s saved, give it a name so you’ll find it.</span></div>` : "";
    li.innerHTML=`<div class="favicon">${it.emoji}</div>
      <div class="body">
        <p class="title">${titleHtml}</p>
        ${it.desc?`<p class="desc">${esc(it.desc)}</p>`:""}
        <p class="meta">${esc(it.site)}</p>
        ${note}
      </div>
      <div class="actions"><button class="btn ${it.failed&&!it.title?"fix":""}">${it.failed&&!it.title?"Name it":"Edit"}</button></div>`;
    li.querySelector(".btn").addEventListener("click",()=>{ editing=idx; render(); });
    list.appendChild(li);
  });
}

