  ];
  const out=[]; let t=1750000000000;
  for(let i=0;i<n;i++){ const c=cats[i%cats.length]; const pre=c.pre[i%c.pre.length]; const w=c.w[(i*7)%c.w.length];
    const folders=[c.top]; if(c.subs.length) folders.push(c.subs[(i*3)%c.subs.length]);
    out.push({ url:"https://ex-"+c.top.toLowerCase()+i+".com/"+w.replace(/\s+/g,"-"),
      title:(pre+w).trim().replace(/\b\w/,x=>x.toUpperCase()), savedAt:t, folders }); t-=172800000; }
  // duplicates of existing library — capitalised folders too, to prove case-merge
  out.splice(3,0,{ url:"https://cooking.nytimes.com/recipes/lemon-pasta/", title:"Lemon Pasta (browser)", savedAt:1740000000000, folders:["Recipes","Italian"] });
  out.splice(20,0,{ url:"https://www.bbc.com/news/future-of-work?utm_source=old", title:"Future of work", savedAt:1739000000000, folders:["Reading"] });
  return out;
}

// merge entries that are the same URL (accumulate their folders), then split fresh vs dupe
function coalesce(list){ const map=new Map();
  list.forEach(x=>{ const id=normalize(x.url); if(map.has(id)){ const e=map.get(id);
      (x.folders||[]).forEach(f=>{ if(!e.folders.includes(f)) e.folders.push(f); }); if(!e.title && x.title) e.title=x.title; }
    else map.set(id,{ url:x.url, title:x.title, savedAt:x.savedAt, folders:[...(x.folders||[])] }); });
  return [...map.values()]; }

let incoming=[];
function toPreview(rawList){
  const list=coalesce(rawList);
  const dupes=list.filter(x=>libIds.has(normalize(x.url))).length;
  const fresh=list.filter(x=>!libIds.has(normalize(x.url)));
  const labelSet=new Set(); let caseMerges=0;
  fresh.forEach(x=>x.folders.forEach(f=>{ const before=canon.has(f.toLowerCase()); const c=canonLabel(f);
    if(before && c!==f) caseMerges++; if(c) labelSet.add(c); }));
  const dated=fresh.filter(x=>x.savedAt>0).map(x=>x.savedAt);
  const keptTitles=fresh.filter(x=>x.title && !/^https?:/i.test(x.title)).length;
  return { total:list.length, fresh, dupes, labels:[...labelSet].sort(), caseMerges,
    dateFrom:dated.length?fmtDate(Math.min(...dated)):null, dateTo:dated.length?fmtDate(Math.max(...dated)):null, keptTitles };
}

const importpanel=document.getElementById("importpanel"), previewpanel=document.getElementById("previewpanel"),
  parsemsg=document.getElementById("parsemsg");

function showPreview(rawList){
  incoming=rawList; const p=toPreview(rawList);
  const chips=p.labels.slice(0,10).map(l=>`<span class="lchip">${esc(l)}</span>`).join("")+(p.labels.length>10?` <span class="note">+${p.labels.length-10} more</span>`:"");
  previewpanel.innerHTML=`
    <h3>Found ${p.total.toLocaleString()} bookmarks. Here's what I'll do:</h3>
    <p class="lead">Nothing happens until you press the button — take a look first.</p>
    <ul class="promises">
      <li><span class="tick">✓</span><div><b>Keep the names you gave them.</b> ${p.keptTitles.toLocaleString()} keep your own titles, untouched.</div></li>
      <li><span class="tick">✓</span><div><b>Folders become labels — both levels, capitals merged.</b> ${p.labels.length} labels in all${p.caseMerges?`, and ${p.caseMerges} folder(s) that only differed by capital letters were merged into labels you already have (so no “Work” vs “work” split)`:""}. A link in “Recipes → Italian” gets <b>both</b> “recipes” and “italian”:<div class="labelmap">${chips||'<span class="note">none</span>'}</div></div></li>
      <li><span class="tick">✓</span><div><b>Keep when you saved each.</b> ${p.dateFrom?`Saves span <b>${p.dateFrom}</b>–<b>${p.dateTo}</b>; that order is preserved.`:"Dates kept where recorded."}</div></li>
      <li><span class="tick">✓</span><div><b>No duplicates.</b> ${p.dupes>0?`<b>${p.dupes}</b> already saved here — skipped, keeping your existing copy and its nicer title.`:"none clash with what you have."}</div></li>
      <li><span class="tick">✓</span><div><b>All at once.</b> ${p.fresh.length.toLocaleString()} new links, no babysitting.</div></li>
    </ul>
    <div class="progress" id="prog" style="display:none"><div></div></div>
    <div class="row" style="justify-content:flex-start">
      <button class="b primary" id="go">Bring in ${p.fresh.length.toLocaleString()} links</button>
      <button class="b ghost" id="cancel">Cancel</button>
    </div>`;
  previewpanel.style.display="block";
  document.getElementById("cancel").onclick=()=>{ previewpanel.style.display="none"; parsemsg.textContent=""; };
  document.getElementById("go").onclick=()=>runImport(p.fresh);
}

function runImport(fresh){
  const prog=document.getElementById("prog"), bar=prog.firstElementChild; prog.style.display="block";
  document.getElementById("go").disabled=true;
  let i=0; const step=Math.max(1,Math.floor(fresh.length/60));
  const tick=setInterval(()=>{ i=Math.min(fresh.length,i+step); bar.style.width=Math.round(i/fresh.length*100)+"%";
    if(i>=fresh.length){ clearInterval(tick);
      fresh.forEach(x=>{ const labels=[...new Set(x.folders.map(canonLabel).filter(Boolean))];
        let host=x.host; try{ host=host||new URL(x.url).hostname.replace(/^www\./,""); }catch{}
        library.push({ url:x.url, host, title:x.title||x.url, labels, note:"", savedAt:x.savedAt||0, imported:true });
        libIds.add(normalize(x.url)); });
      importpanel.style.display="none"; previewpanel.style.display="none";
      document.getElementById("libraryhead").style.display="block"; renderLibrary();
    } },70);
}

let sort="new";
function renderLibrary(){
  const arr=[...library];
  if(sort==="new") arr.sort((a,b)=>b.savedAt-a.savedAt);
  else if(sort==="old") arr.sort((a,b)=>a.savedAt-b.savedAt);
  else arr.sort((a,b)=>a.title.toLowerCase()<b.title.toLowerCase()?-1:1);
  document.getElementById("count").textContent=library.length.toLocaleString()+" links";
  const list=document.getElementById("list"), more=document.getElementById("more"); list.innerHTML=""; const cap=200;
  arr.slice(0,cap).forEach(it=>{ const li=document.createElement("li"); li.className="item";
    li.innerHTML=`<div class="favicon">${emojiFor(it.host)}</div>
      <div style="min-width:0;flex:1">
        <p class="title"><a href="${it.url}" target="_blank" rel="noopener">${esc(it.title)}</a>${it.imported?'<span class="imported">imported</span>':''}</p>
        <p class="meta">${esc(it.host)}${it.savedAt?" · saved "+fmtDate(it.savedAt):""}</p>
        <div class="badges">${it.labels.map(l=>`<span class="lchip">${esc(l)}</span>`).join("")}</div>
      </div>`;
    list.appendChild(li); });
  more.textContent = arr.length>cap ? `…and ${(arr.length-cap).toLocaleString()} more (showing first ${cap})` : "";
}

