// export → normal bookmarks file, with labels as folders and notes as descriptions
document.getElementById("export").onclick=()=>{
  const byLabel=new Map(), noLabel=[];
  library.forEach(it=>{ if(it.labels.length) it.labels.forEach(l=>{ if(!byLabel.has(l)) byLabel.set(l,[]); byLabel.get(l).push(it); }); else noLabel.push(it); });
  const link=(it,ind)=>{ const ad=it.savedAt?` ADD_DATE="${Math.floor(it.savedAt/1000)}"`:"";
    let s=`${ind}<DT><A HREF="${esc(it.url)}"${ad}>${esc(it.title)}</A>\n`; if(it.note) s+=`${ind}<DD>${esc(it.note)}\n`; return s; };
  let html=`<!DOCTYPE NETSCAPE-Bookmark-file-1>\n<META HTTP-EQUIV="Content-Type" CONTENT="text/html; charset=UTF-8">\n<TITLE>Bookmarks</TITLE>\n<H1>Bookmarks</H1>\n<DL><p>\n`;
  [...byLabel.keys()].sort().forEach(l=>{ html+=`  <DT><H3>${esc(l)}</H3>\n  <DL><p>\n`;
    byLabel.get(l).forEach(it=>html+=link(it,"    ")); html+=`  </DL><p>\n`; });
  noLabel.forEach(it=>html+=link(it,"  ")); html+=`</DL><p>\n`;
  const a=document.createElement("a"); a.href=URL.createObjectURL(new Blob([html],{type:"text/html"}));
  a.download="my-bookmarks.html"; a.click(); URL.revokeObjectURL(a.href);
};
